1	import { PrismaClient } from "../generated/prisma/client";
2	import { PrismaLibSql } from "@prisma/adapter-libsql";
3	
4	const globalForPrisma = globalThis as unknown as {
5	  prisma: PrismaClient | undefined;
6	};
7	
8	/**
9	 * DB connection, cross-platform.
10	 *
11	 * - Local dev (Windows / SQLite, DATABASE_URL="file:..."): the `prisma-client`
12	 *   generator's plain client resolves a relative `file:` path against the wrong
13	 *   directory and silently hits an EMPTY database (this is what broke login).
14	 *   Using the libSQL driver adapter resolves the path relative to CWD — the same
15	 *   way scripts/repair-sqlite-db.ts connects — so the app reads prisma/dev.db.
16	 * - Prod (Linux / Postgres, DATABASE_URL="postgres..."): the plain client works
17	 *   as before (absolute URL, no relative-path issue). Left unchanged so the
18	 *   deployed server's behavior is untouched.
19	 *
20	 * The schema provider itself is swapped to match DATABASE_URL by
21	 * scripts/prisma-generate.js (run on postinstall), so the generated client
22	 * always matches the target database on each platform.
23	 */
24	function createPrismaClient(): PrismaClient {
25	  const url = process.env.DATABASE_URL ?? "";
26	  if (url.startsWith("file:") || url.startsWith("libsql:")) {
27	    return new PrismaClient({ adapter: new PrismaLibSql({ url }) });
28	  }
29	  return new PrismaClient();
30	}
31	
32	export const prisma = globalForPrisma.prisma ?? createPrismaClient();
33	
34	if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

