5	/** Admin-panel sub-pages — require a valid session; redirect to /adminpanel on failure */
6	const ADMIN_PANEL_PREFIXES = [
7	  "/adminpanel/superadmin",
8	  "/adminpanel/teacher",
9	];
10	
11	/** Student/user page routes — require a valid session; redirect to /login on failure */
12	const PROTECTED_PAGE_PREFIXES = [
13	  "/dashboard",
14	  "/library",
15	  "/quizzes",
16	  "/codes",
17	  "/complete-profile",
18	  "/account",
19	];
20	
21	/** Protected API routes — require a valid session; return 401 JSON on failure */
22	const PROTECTED_API_PREFIXES = [
23	  "/api/library",
24	  "/api/quizzes",
25	  "/api/progress",
26	  "/api/auth/complete-profile",
27	];
28	
29	/** Paths under /courses that require auth (the learning room) */
30	function isProtectedCourseRoute(pathname: string) {
31	  return /^\/courses\/[^/]+\/learn(\/.*)?$/.test(pathname);
32	}
33	
34	function isProtectedPlanRoute(pathname: string) {
35	  return /^\/plans\/[^/]+\/learn(\/.*)?$/.test(pathname);
36	}
37	
38	/** Public API routes under /api/courses that need no session */
39	function isPublicCoursesApi(pathname: string) {
40	  return pathname === "/api/courses" || /^\/api\/courses(\/[^/]+\/preview)?$/.test(pathname);
41	}
42	
43	function isPublicPlansApi(pathname: string) {
44	  return pathname === "/api/plans" || /^\/api\/plans\/[^/]+$/.test(pathname);
45	}
46	
47	function startsWithAny(pathname: string, prefixes: string[]) {
48	  return prefixes.some((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`));
49	}
50	
51	/** /adminpanel login page itself — exact match only, never prefix */
52	function isAdminLoginPage(pathname: string) {
53	  return pathname === "/adminpanel" || pathname === "/adminpanel/";
54	}
