7	export async function checkCourseEnrollment(userId: string, courseId: string): Promise<boolean> {
8	  const code = await prisma.accessCode.findFirst({
9	    where: {
10	      courseId,
11	      studentId: userId,
12	      isActive: true, // Wait, used codes can keep isActive true or false depending on DB schema logic. Let's make sure it handles used codes correctly. In the schema, a code has studentId set once redeemed. In route.ts it was checked with: prisma.accessCode.findFirst({ where: { courseId: course.id, studentId: session.id, isActive: true } })
