1	import { prisma } from "@/lib/prisma";
2	import { POINTS } from "@/lib/points";
3	
4	export type ReferralStatus = "PENDING" | "QUALIFIED" | "REWARDED" | "INVALID";
5	
6	export class ReferralService {
7	  /**
8	   * Registers a new PENDING referral link when student B signs up using Student A's referral code.
9	   * Does NOT award any points on raw signup to prevent bot farming.
10	   */
11	  public static async registerPendingReferral(
12	    inviterId: string,
13	    invitedId: string
14	  ): Promise<boolean> {
15	    if (inviterId === invitedId) {
16	      console.warn(`[ReferralService] Rejected self-referral for user ${inviterId}`);
17	      return false;
18	    }
19	
20	    try {
21	      await prisma.referral.create({
22	        data: {
23	          inviterId,
24	          invitedId,
25	          status: "PENDING",
26	        },
27	      });
28	      return true;
29	    } catch (err) {
30	      // Handles UNIQUE(invitedId) constraint if user was already referred
31	      console.warn(`[ReferralService] User ${invitedId} already has a referral record.`);
32	      return false;
33	    }
34	  }
35	
36	  /**
37	   * Qualifies and awards referral rewards (POINTS.REFERRAL to inviter & invited student)
38	   * upon a valid paid course purchase or access code redemption.
39	   * 
40	   * Atomically transitions status PENDING -> QUALIFIED -> REWARDED inside a transaction.
41	   */
42	  public static async qualifyAndRewardReferral(
43	    invitedStudentId: string,
44	    qualifyingPurchaseId: string
45	  ): Promise<{ rewarded: boolean; pointsAwarded: number }> {
46	    return await prisma.$transaction(async (tx) => {
47	      const referral = await tx.referral.findUnique({
48	        where: { invitedId: invitedStudentId },
49	      });
50	
51	      if (!referral) {
52	        return { rewarded: false, pointsAwarded: 0 };
53	      }
54	
55	      // Must be in PENDING status and not previously rewarded
56	      if (referral.status !== "PENDING") {
57	        return { rewarded: false, pointsAwarded: 0 };
58	      }
59	
60	      // Transition to REWARDED state atomically
61	      await tx.referral.update({
62	        where: { id: referral.id },
63	        data: {
64	          status: "REWARDED",
65	          qualifyingPurchaseId,
66	          rewardedAt: new Date(),
67	        },
68	      });
69	
70	      // Award POINTS.REFERRAL (+50 XP) to inviter & invited student
71	      const rewardPoints = POINTS.REFERRAL ?? 50;
72	      await tx.user.update({
73	        where: { id: referral.inviterId },
74	        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
75	      });
76	
77	      await tx.user.update({
78	        where: { id: referral.invitedId },
79	        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
80	      });
81	
82	      // Audit Log
83	      await tx.auditLog.create({
84	        data: {
85	          userId: referral.invitedId,
86	          action: "REFERRAL_REWARDED",
87	          ip: "127.0.0.1",
88	          metadata: JSON.stringify({
89	            inviterId: referral.inviterId,
90	            invitedId: referral.invitedId,
91	            qualifyingPurchaseId,
92	            rewardPoints,
93	          }),
94	        },
95	      }).catch(() => {});
96	
97	      console.log(`[ReferralService] Successfully rewarded ${rewardPoints} XP to inviter ${referral.inviterId} and invited ${referral.invitedId}`);
98	
99	      return { rewarded: true, pointsAwarded: rewardPoints };
100	    });
101	  }
102	
103	  /**
104	   * Retrieves summary telemetry of referrals for admin security dashboard.
105	   */
106	  public static async getReferralTelemetry(): Promise<{
107	    pending: number;
108	    qualified: number;
109	    rewarded: number;
110	    invalid: number;
111	    total: number;
112	  }> {
113	    const [pending, qualified, rewarded, invalid, total] = await Promise.all([
114	      prisma.referral.count({ where: { status: "PENDING" } }),
115	      prisma.referral.count({ where: { status: "QUALIFIED" } }),
116	      prisma.referral.count({ where: { status: "REWARDED" } }),
117	      prisma.referral.count({ where: { status: "INVALID" } }),
118	      prisma.referral.count(),
119	    ]);
120	
121	    return { pending, qualified, rewarded, invalid, total };
122	  }
123	}

1	import { prisma } from "@/lib/prisma";
2	import { OtpQuotaManager, OtpActionCategory } from "./OtpQuotaManager";
3	import { sendVerificationSms } from "@/lib/aws-sms";
4	import { createPhoneVerificationChallenge, setPhoneVerificationCookie } from "@/lib/auth";
5	
6	export interface RequestOtpParams {
7	  userId?: string;
8	  phone: string;
9	  actionCategory: OtpActionCategory;
10	}
11	
12	export interface RequestOtpResult {
13	  sent: boolean;
14	  deferred: boolean;
15	  code?: string;
16	  message: string;
17	  quotaRemaining: number;
18	}
19	
20	const ACTION_PRIORITY: Record<OtpActionCategory, number> = {
21	  PASSWORD_RESET: 1,  // Highest priority
22	  COURSE_PURCHASE: 2,
23	  CODE_REDEMPTION: 3,
24	  PHONE_CHANGE: 4,
25	  SIGNUP: 5,          // Lowest priority
26	};
27	
28	export class OtpService {
29	  /**
30	   * Request OTP dispatch.
31	   * If daily WhatsApp quota (< 250) is available:
32	   *   - Atomically reserves quota slot and dispatches SMS/WhatsApp.
33	   * If daily quota is exhausted:
34	   *   - Defers verification, enqueues request into OtpQueueItem with priority ranking,
35	   *     and returns deferred status so user profile can proceed in unverified mode.
36	   */
37	  public static async requestOtp(params: RequestOtpParams): Promise<RequestOtpResult> {
38	    const { userId, phone, actionCategory } = params;
39	
40	    // 1. Reserve quota slot atomically
41	    const quotaRes = await OtpQuotaManager.reserveQuota(actionCategory);
42	
43	    // Generate random 6-digit OTP code
44	    const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
45	
46	    if (quotaRes.allowed) {
47	      // Quota available -> Send WhatsApp OTP immediately
48	      try {
49	        await sendVerificationSms(phone, otpCode);
50	        const challengeToken = await createPhoneVerificationChallenge(phone, otpCode);
51	        await setPhoneVerificationCookie(challengeToken);
52	
53	        return {
54	          sent: true,
55	          deferred: false,
56	          code: otpCode,
57	          message: "تم إرسال رمز التحقق عبر WhatsApp بنجاح",
58	          quotaRemaining: quotaRes.remaining,
59	        };
60	      } catch (err) {
61	        console.error("[OtpService] Failed to send WhatsApp OTP:", err);
62	        // Release reserved quota slot so unused quota isn't wasted
63	        await OtpQuotaManager.releaseQuota(actionCategory);
64	      }
65	    }
66	
67	    // 2. Daily quota exhausted OR provider call failed -> Defer verification
68	    if (userId) {
69	      const priority = ACTION_PRIORITY[actionCategory] ?? 5;
70	
71	      await prisma.otpQueueItem.create({
72	        data: {
73	          userId,
74	          phone,
75	          actionType: actionCategory,
76	          priority,
77	          status: "QUEUED",
78	        },
79	      });
80	
81	      // Update user verification status to WAITING_FOR_OTP
82	      await prisma.user.update({
83	        where: { id: userId },
84	        data: {
85	          isVerified: false,
86	          verificationStatus: "WAITING_FOR_OTP",
87	        },
88	      });
89	    }
90	
91	    return {
92	      sent: false,
93	      deferred: true,
94	      message: "تم بلوغ الحد اليومي لرسائل التحقق السريعة. تم إدراج طلبك في قائمة الانتظار، ويمكنك متابعة استخدام حسابك الآن.",
95	      quotaRemaining: 0,
96	    };
97	  }
98	
99	  /**
100	   * Worker method called by cron or admin trigger to process queued OTP items
101	   * whenever daily quota becomes available.
102	   */
103	  public static async processQueuedOtps(maxBatchSize: number = 20): Promise<{
104	    processed: number;
105	    sent: number;
106	    failed: number;
107	  }> {
108	    let sentCount = 0;
109	    let failedCount = 0;
110	
111	    // Fetch queued items ordered by priority (1 highest) and queue timestamp
112	    const queuedItems = await prisma.otpQueueItem.findMany({
113	      where: { status: "QUEUED" },
114	      orderBy: [{ priority: "asc" }, { queuedAt: "asc" }],
115	      take: maxBatchSize,
116	    });
117	
118	    for (const item of queuedItems) {
119	      // Check quota reservation for item's action
120	      const quotaRes = await OtpQuotaManager.reserveQuota(item.actionType as OtpActionCategory);
121	      if (!quotaRes.allowed) {
122	        // Quota still exhausted -> Stop processing batch
123	        break;
124	      }
125	
126	      try {
127	        const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
128	        await sendVerificationSms(item.phone, otpCode);
129	
130	        // Update queue item
131	        await prisma.otpQueueItem.update({
132	          where: { id: item.id },
133	          data: {
134	            status: "SENT",
135	            processedAt: new Date(),
136	          },
137	        });
138	
139	        // Update user to VERIFIED
140	        await prisma.user.update({
141	          where: { id: item.userId },
142	          data: {
143	            isVerified: true,
144	            verificationStatus: "VERIFIED",
145	          },
146	        });
147	
148	        sentCount++;
149	      } catch (err) {
150	        console.error(`[OtpService] Processing queued item ${item.id} failed:`, err);
151	        failedCount++;
152	
153	        await prisma.otpQueueItem.update({
154	          where: { id: item.id },
155	          data: {
156	            retryCount: { increment: 1 },
157	            status: item.retryCount >= 3 ? "FAILED" : "QUEUED",
158	          },
159	        });
160	      }
161	    }
162	
163	    return {
164	      processed: queuedItems.length,
165	      sent: sentCount,
166	      failed: failedCount,
167	    };
168	  }
169	}

1	import { NextRequest, NextResponse } from "next/server";
2	import { getSession } from "@/lib/auth";
