5	import { generateVerificationCode, sendVerificationCode } from "@/lib/whatsapp";
6	import { createPhoneVerificationChallenge, setPhoneVerificationCookie } from "@/lib/auth";
7	import { checkCooldown } from "@/lib/cooldown";
8	
9	export async function POST(req: NextRequest) {
10	  try {
11	    const { phone, forceChannel } = await req.json();
12	    if (!phone) {
13	      return NextResponse.json({ error: "رقم الهاتف مطلوب" }, { status: 400 });
14	    }
15	
16	    const normalized = normalizeEgyptPhone(String(phone));
17	
18	    const user = await prisma.user.findFirst({
19	      where: { phone: normalized, role: "student" },
20	      select: { id: true },
21	    });
22	
23	    if (!user) {
24	      return NextResponse.json(
25	        { error: "لا يوجد حساب طالب مرتبط بهذا الرقم" },
26	        { status: 404 }
27	      );
28	    }
29	
30	    const bypass = isPhoneVerificationBypassed();
31	
32	    if (bypass) {
33	      return NextResponse.json({ success: true, bypass, channel: "dev" });
34	    }
35	
36	    // Server-side cooldown validation: 60 seconds per phone number
37	    const cooldownCheck = checkCooldown(normalized, 60000);
38	    if (!cooldownCheck.allowed) {
39	      return NextResponse.json(
40	        { error: `يرجى الانتظار ${cooldownCheck.remainingSeconds} ثانية قبل محاولة إرسال الرمز مجدداً.` },
41	        { status: 429 }
42	      );
43	    }
44	
45	    // Generate code and send via requested channel (or WhatsApp with SMS fallback)
46	    const code = generateVerificationCode();
47	    const result = await sendVerificationCode(normalized, code, forceChannel === "sms" ? "sms" : undefined);
48	
49	    // Store the code hash in a secure HTTP-only cookie for verification
50	    const challengeToken = await createPhoneVerificationChallenge(normalized, code);
51	    await setPhoneVerificationCookie(challengeToken);
52	
53	    return NextResponse.json({ success: true, channel: result.channel, bypass });
54	  } catch (err) {
55	    console.error("forgot-password error:", err);
56	    return NextResponse.json(
57	      { error: "حدث خطأ أثناء معالجة الطلب" },
58	      { status: 500 }
59	    );
60	  }
61	}

1	import { NextRequest, NextResponse } from "next/server";
2	import bcrypt from "bcryptjs";
