11	export async function POST(req: NextRequest) {
12	  try {
13	    const { phone, verificationCode, newPassword } = await req.json();
14	
15	    if (!phone || !newPassword) {
16	      return NextResponse.json(
17	        { error: "جميع الحقول مطلوبة" },
18	        { status: 400 }
19	      );
20	    }
21	
22	    if (String(newPassword).length < 6) {
23	      return NextResponse.json(
24	        { error: "كلمة المرور يجب أن تكون 6 أحرف على الأقل" },
25	        { status: 400 }
26	      );
27	    }
28	
29	    const normalized = normalizeEgyptPhone(String(phone));
30	
31	    if (!isPhoneVerificationBypassed()) {
32	      if (!verificationCode) {
33	        return NextResponse.json(
34	          { error: "رمز التحقق مطلوب" },
35	          { status: 400 }
36	        );
37	      }
38	      const isValid = await verifyPhoneVerificationCookie(normalized, String(verificationCode));
39	      if (!isValid) {
40	        return NextResponse.json(
