15	/**
16	 * Attributes purchase revenue to a teacher per platform rules:
17	 * - Case A: Promo code entered at purchase time matching content teacher's active code (<350d).
18	 * - Case B: Student previously referred by content teacher on signup (only attributes for content teacher's own content).
19	 */
20	export async function processTeacherAttribution(input: ProcessAttributionInput) {
21	  const db = input.tx || prisma;
22	  const {
23	    studentId,
24	    teacherIdOfContent,
25	    amount,
26	    purchaseType,
27	    courseId,
28	    folderId,
29	    videoId,
30	    promoCodeInput,
31	  } = input;
32	
33	  if (amount <= 0 || !teacherIdOfContent) return;
34	
35	  const now = new Date();
36	  const PROMO_EXPIRY_MS = 350 * 24 * 60 * 60 * 1000;
37	
38	  // Case A: Explicit promo code entered at purchase time
39	  if (promoCodeInput) {
40	    const codeUpper = String(promoCodeInput).trim().toUpperCase();
41	    const promoTeacher = await db.user.findFirst({
42	      where: {
43	        role: "teacher",
44	        promoProgramEnabled: true,
45	        promoCode: codeUpper,
46	      },
47	      select: { id: true, promoCodeCreatedAt: true },
48	    });
49	
50	    if (promoTeacher && promoTeacher.id === teacherIdOfContent && promoTeacher.promoCodeCreatedAt) {
51	      if (now.getTime() - new Date(promoTeacher.promoCodeCreatedAt).getTime() <= PROMO_EXPIRY_MS) {
52	        await db.teacherReferralAttribution.create({
53	          data: {
54	            teacherId: promoTeacher.id,
55	            studentId,
56	            purchaseType,
57	            courseId,
58	            folderId,
59	            videoId,
60	            amount,
61	            promoCodeUsed: codeUpper,
62	          },
63	        });
64	        return;
65	      }
66	    }
67	  }
68	
69	  // Case B: Account-level referral from signup
70	  const student = await db.user.findUnique({
71	    where: { id: studentId },
72	    select: { referredByTeacherId: true },
73	  });
74	
75	  if (student?.referredByTeacherId && student.referredByTeacherId === teacherIdOfContent) {
76	    const referringTeacher = await db.user.findUnique({
77	      where: { id: student.referredByTeacherId },
78	      select: { id: true, promoProgramEnabled: true },
79	    });
80	
81	    if (referringTeacher?.promoProgramEnabled) {
82	      await db.teacherReferralAttribution.create({
83	        data: {
84	          teacherId: referringTeacher.id,
85	          studentId,
86	          purchaseType,
87	          courseId,
88	          folderId,
89	          videoId,
90	          amount,
91	        },
92	      });
93	    }
94	  }
95	}

