7	
8	      try {
9	      const session = await getSession();
10	      if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
11	
12	      const { id: quizId } = await params;
13	      const quiz = await prisma.quiz.findUnique({
14	        where: { id: quizId },
