26	        },
27	      });
28	
29	      if (!quiz) return NextResponse.json({ error: "الاختبار غير موجود" }, { status: 404 });
30	
31	      const canAccessAsTeacher = session.role === "teacher" && (
32	        quiz.folder?.course?.teacherId === session.id || quiz.planLessonId !== null
33	      );
34	      
35	      let canAccessAsStudent = false;
36	      if (quiz.folderId && quiz.folder) {
37	        const hasCourseAccess = await prisma.accessCode.findFirst({
38	          where: { courseId: quiz.folder.courseId, studentId: session.id, isActive: true },
39	          select: { id: true },
40	        });
41	        if (hasCourseAccess) canAccessAsStudent = true;
42	      } else if (quiz.planLessonId && quiz.planLesson) {
43	        const hasPlanAccess = await prisma.planEnrollment.findFirst({
44	          where: { planId: quiz.planLesson.planId, studentId: session.id, expiresAt: { gt: new Date() } },
45	          select: { id: true },
46	        });
47	        if (hasPlanAccess) canAccessAsStudent = true;
48	      }
49	
50	      if (!canAccessAsTeacher && !canAccessAsStudent) {
51	        return NextResponse.json({ error: "لا يوجد صلاحية للوصول" }, { status: 403 });
52	      }
53	
54	      const isStudent = session.role === "student";
55	
56	      // Check if student already completed this quiz
57	      if (isStudent) {
58	        const existingResult = await prisma.quizResult.findUnique({
59	          where: { studentId_quizId: { studentId: session.id, quizId } },
60	        });
61	        if (existingResult) {
62	          if (!existingResult.allowRetake) {
63	            return NextResponse.json({
64	              alreadyCompleted: true,
65	              result: {
66	                score: existingResult.score,
67	                totalQ: existingResult.totalQ,
68	                completedAt: existingResult.completedAt,
