77	            const cooldownMs = cooldownHours * 3_600_000;
78	            const elapsed    = Date.now() - new Date(existingResult.completedAt).getTime();
79	            if (elapsed < cooldownMs) {
80	              return NextResponse.json({
81	                alreadyCompleted: true,
82	                cooldownRemainingMs: cooldownMs - elapsed,
83	                result: {
84	                  score: existingResult.score,
85	                  totalQ: existingResult.totalQ,
86	                  completedAt: existingResult.completedAt,
87	                },
88	                quiz: { id: quiz.id, title: quiz.title, courseId: quiz.folder?.courseId ?? 'plan', course: quiz.folder?.course },
89	              });
90	            }
91	          }
92	
93	          // Reset QuizResult for retake
94	          await prisma.quizResult.update({
