97	          });
98	        } else {
99	          // Create initial QuizResult with startedAt
100	          await prisma.quizResult.create({
101	            data: {
102	              studentId: session.id,
103	              quizId,
104	              score: 0,
105	              totalQ: 0,
106	              startedAt: new Date(),
107	              allowRetake: false,
108	            },
109	          });
110	        }
111	      }
112	
113	      const questions = isStudent
114	        ? quiz.questions.map((question: any) => {
115	            const { correctAnswer: _ca, ...q } = question;
116	            return q;
117	          })
118	        : quiz.questions;
119	
120	      return NextResponse.json({
121	        quiz: {
122	          id: quiz.id,
123	          title: quiz.title,
124	          timeLimitMinutes: (quiz as any).timeLimitMinutes,
125	          questions,
126	          folderId: quiz.folderId,
127	          courseId: quiz.folder?.courseId ?? 'plan',
128	          course: quiz.folder?.course,
129	        },
130	        timeLimitMinutes: (quiz as any).timeLimitMinutes,
131	      });
132	    } catch (error) {
133	        console.error("[quizzes/[id]] error:", error);
134	        return NextResponse.json(
135	          { error: "حدث خطأ داخلي" },
136	          { status: 500 }
137	        );
138	      }
139	}

