5	import crypto from "crypto";
6	
7	const MAX_BULK = 200;
8	
9	function generateCode(prefix?: string): string {
10	  const hex = crypto.randomBytes(4).toString("hex").toUpperCase();
11	  return prefix ? `${prefix.toUpperCase()}-${hex}` : hex;
12	}
13	
14	export async function POST(req: NextRequest) {
15	  try {
16	    const session = await getSession();
17	
18	    if (session && session.role === "superadmin") {
19	      try {
20	        await logAdminAction({
21	          adminId: session.id,
22	          adminName: session.name,
23	          action: "SUPERADMIN_ACTION",
24	          targetType: "API_ROUTE",
25	          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
26	          targetName: req.method,
27	        });
28	      } catch (e) {}
29	    }
30	    if (!session || (session.role !== "teacher" && session.role !== "superadmin")) {
31	      return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
32	    }
33	
34	    const body = await req.json();
35	    const { courseId, planId, prefix, format } = body as {
36	      courseId?: string;
37	      planId?: string;
38	      count?: number;
39	      prefix?: string;
40	      format?: string;
41	    };
42	    const count = Math.min(Math.max(1, Math.floor(Number(body.count) || 1)), MAX_BULK);
43	
44	    const cleanPrefix = prefix ? String(prefix).trim().toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 10) : undefined;
45	
46	    // Plan bulk codes
47	    if (planId) {
48	      const plan = await prisma.plan.findUnique({
49	        where: { id: planId },
50	        select: { id: true, title: true },
51	      });
52	      if (!plan) return NextResponse.json({ error: "الخطة غير موجودة" }, { status: 404 });
53	
54	      const codes: string[] = [];
55	      const maxAttempts = count * 3;
56	      let attempts = 0;
57	      while (codes.length < count && attempts < maxAttempts) {
58	        attempts++;
59	        const code = generateCode(cleanPrefix);
60	        if (!codes.includes(code)) {
61	          const exists = await prisma.planAccessCode.findUnique({ where: { code }, select: { id: true } });
62	          if (!exists) codes.push(code);
63	        }
64	      }
65	
66	      if (codes.length < count) {
67	        return NextResponse.json({ error: `تعذر إنشاء ${count} كود فريد — حاول بعدد أقل أو بادئة مختلفة` }, { status: 409 });
68	      }
69	
70	      const created = await prisma.$transaction(
71	        codes.map((code) => prisma.planAccessCode.create({ data: { code, planId } }))
72	      );
73	
74	      if (format === "csv") {
75	        const csvHeader = "code,planId,planTitle,createdAt";
76	        const csvRows = created.map(
77	          (c) => `${c.code},${c.planId},"${plan.title.replace(/"/g, '""')}",${c.createdAt.toISOString()}`
78	        );
79	        const csvContent = [csvHeader, ...csvRows].join("\n");
80	        const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
81	
82	        return new NextResponse(csvContent, {
83	          status: 200,
84	          headers: {
85	            "Content-Type": "text/csv; charset=utf-8",
86	            "Content-Disposition": `attachment; filename="plan-codes-${planId}-${timestamp}.csv"`,
87	          },
88	        });
89	      }
90	
91	      return NextResponse.json({ codes: created, count: created.length }, { status: 201 });
92	    }
93	
94	    // Course bulk codes
95	    if (!courseId) {
96	      return NextResponse.json({ error: "courseId أو planId مطلوب" }, { status: 400 });
97	    }
98	
99	    const courseWhere = session.role === "superadmin" ? { id: courseId } : { id: courseId, teacherId: session.id };
100	    const course = await prisma.course.findFirst({
101	      where: courseWhere,
102	      select: { id: true, title: true },
103	    });
104	    if (!course) {
105	      return NextResponse.json({ error: "الكورس غير موجود" }, { status: 404 });
106	    }
107	
108	    const codes: string[] = [];
109	    const maxAttempts = count * 3;
110	    let attempts = 0;
111	    while (codes.length < count && attempts < maxAttempts) {
112	      attempts++;
113	      const code = generateCode(cleanPrefix);
114	      if (!codes.includes(code)) {
115	        const exists = await prisma.accessCode.findUnique({ where: { code }, select: { id: true } });
116	        if (!exists) codes.push(code);
117	      }
118	    }
119	
120	    if (codes.length < count) {
121	      return NextResponse.json({ error: `تعذر إنشاء ${count} كود فريد — حاول بعدد أقل أو بادئة مختلفة` }, { status: 409 });
122	    }
123	
124	    const created = await prisma.$transaction(
125	      codes.map((code) => prisma.accessCode.create({ data: { code, courseId } }))
126	    );
127	
128	    if (format === "csv") {
129	      const csvHeader = "code,courseId,courseTitle,createdAt";
130	      const csvRows = created.map(
131	        (c) => `${c.code},${c.courseId},"${course.title.replace(/"/g, '""')}",${c.createdAt.toISOString()}`
132	      );
133	      const csvContent = [csvHeader, ...csvRows].join("\n");
134	      const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
135	
136	      return new NextResponse(csvContent, {
137	        status: 200,
138	        headers: {
139	          "Content-Type": "text/csv; charset=utf-8",
140	          "Content-Disposition": `attachment; filename="codes-${courseId}-${timestamp}.csv"`,
141	        },
142	      });
143	    }
144	
145	    return NextResponse.json({ codes: created, count: created.length }, { status: 201 });
146	  } catch (error) {
